{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Methoxsalen, the closest structural analogue and a methoxycoumarin, shows relatively low systemic bioavailability in humans, directly supporting low oral bioavailability for the query's coumarin scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Apocynin, a small methoxyphenol sharing the 4-hydroxy-3-methoxyphenyl motif, has human oral bioavailability below 10%, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Ferulic acid, another methoxyphenol-related compound, shows only 3-10% oral bioavailability in humans, supporting low systemic availability for this phenolic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Isoeugenol, a small methoxyphenol, has human oral bioavailability of 35.8-39.0%, which is contradictory to a low prediction, but its lower structural similarity and lack of the coumarin lactone reduce transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C22"],
      "claim": "Curcumin, a polyphenol with methoxyphenol groups, has absolute oral bioavailability of barely 1% in humans, supporting low F for polyphenolic natural products despite lower structural similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Chrysin, a related polyphenolic natural product, has predicted absolute human bioavailability of only 0.003-0.02%, reinforcing the pattern of low oral bioavailability for phenolic natural products.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue, methoxsalen, is a methoxycoumarin with relatively low human systemic bioavailability, and multiple smaller methoxyphenols also show <10% oral bioavailability. The only supportive high-F evidence, isoeugenol, is less structurally similar and lacks the coumarin lactone. Overall, the transferable human evidence favors F < 20%.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for scopoletin itself is provided.",
    "The influence of the coumarin lactone and phenolic conjugation on first-pass metabolism is inferred from analogues rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

